#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill, for deploying openBatteryFlux's accounts to
# Vercel with a hosted database.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=11

# Run from the repository root, whatever directory the human ran this from.
ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)
cd "$ROOT"
ENV_FILE="${ENV_FILE:-$ROOT/.env}"

# _py is the interpreter that has the project's dependencies installed.
_py() {
  if [[ -x "$ROOT/.venv/bin/python" ]]; then printf '%s' "$ROOT/.venv/bin/python"
  else printf 'python3'; fi
}

# _load_env exports what the wizard has captured so far, for the tools it runs.
# It parses KEY=VALUE rather than sourcing the file: a sender such as
# "openBatteryFlux <no-reply@example.com>" is a perfectly ordinary value here
# and would be a redirection if the shell read it.
_load_env() {
  [[ -f "$ENV_FILE" ]] || return 0
  local line key value
  while IFS= read -r line || [[ -n "$line" ]]; do
    [[ -z "$line" || "$line" == \#* ]] && continue
    [[ "$line" == *=* ]] || continue
    key=${line%%=*}
    value=${line#*=}
    export "$key=$value"
  done < "$ENV_FILE"
}

# _vercel_ready: the CLI is installed, signed in and the directory is linked.
_vercel_ready() {
  command -v vercel >/dev/null 2>&1 || return 1
  vercel whoami >/dev/null 2>&1 || return 1
  [[ -f "$ROOT/.vercel/project.json" ]]
}

# _vercel_env NAME VALUE ENV adds or replaces one variable on Vercel.
_vercel_env() {
  local name="$1" value="$2" environment="$3"
  vercel env rm "$name" "$environment" --yes >/dev/null 2>&1 || true
  if printf '%s' "$value" | vercel env add "$name" "$environment" >/dev/null 2>&1; then
    printf '  %s✓ set%s Vercel %s (%s)\n' "$GREEN" "$RESET" "$name" "$environment"
    return 0
  fi
  return 1
}

# _resend_check KEY FROM asks Resend what this key can see and whether FROM is
# on a domain it has verified. 0 = good, 2 = the API was unreachable, anything
# else is a problem worth reading before continuing.
_resend_check() {
  "$(_py)" - "$1" "$2" <<'PY'
import json
import re
import sys
import urllib.error
import urllib.request

key, sender = sys.argv[1], sys.argv[2]
request = urllib.request.Request("https://api.resend.com/domains",
                                 headers={"Authorization": "Bearer " + key})
try:
    with urllib.request.urlopen(request, timeout=15) as response:
        payload = json.load(response)
except urllib.error.HTTPError as err:
    body = err.read().decode("utf-8", "replace")[:200].strip()
    print("  Resend refused the key: HTTP %s %s" % (err.code, body))
    if err.code in (401, 403):
        print("  that usually means the key is wrong, revoked, or not copied whole")
    sys.exit(1)
except Exception as err:  # offline, DNS, proxy
    print("  could not reach api.resend.com (%s)" % err)
    sys.exit(2)

domains = payload.get("data") or []
verified = [d for d in domains if d.get("status") == "verified"]
print("  the key works: %d domain(s) in the account, %d verified%s"
      % (len(domains), len(verified),
         (" — " + ", ".join(d.get("name", "?") for d in verified)) if verified else ""))

match = re.search(r"@([^>\s]+)", sender)
if not match:
    print("  the From address has no domain: %r" % sender)
    sys.exit(3)
domain = match.group(1).lower()
if domain == "resend.dev":
    print("  @resend.dev only delivers to your own address: Resend's test mode")
    print("  refuses everyone else, so real users would never get the link.")
    sys.exit(4)
if domain not in {d.get("name", "").lower() for d in verified}:
    print("  %s is not verified in this account yet, so Resend will reject" % domain)
    print("  every message until the DNS records are in place.")
    sys.exit(4)
print("  the sender is on a verified domain, so anyone can receive the link")
PY
}

banner "Accounts and email on the deployed site"

# ── 1. the hosted database ────────────────────────────────────────────────
stage "Turso: the database accounts live in"
say "A Vercel function has no writable disk, so accounts cannot live in a file"
say "there. They go in a hosted SQLite database (Turso). The cell library is"
say "read-only and unaffected — it still ships inside the deployment."
open_url "https://app.turso.tech/"
step "If you have no database yet: create one, name it openbatteryflux, pick a"
step "region near your users."
step "Open the database and copy its URL (starts with turso://)."
ask OBF_DATABASE_URL "Paste the database URL:"
step "In the database's Tokens tab, create a token and copy it (it is shown once)."
ask_secret OBF_DATABASE_TOKEN "Paste the token:"
if [[ -z "${OBF_DATABASE_URL:-}" || -z "${OBF_DATABASE_TOKEN:-}" ]]; then
  warn "Both values are needed; stopping here. Re-run when you have them."
  exit 1
fi
write_env OBF_DATABASE_URL "$OBF_DATABASE_URL"
write_env OBF_DATABASE_TOKEN "$OBF_DATABASE_TOKEN"
note "$ENV_FILE is gitignored, so the token is not committed."

# ── 2. the administrator address ──────────────────────────────────────────
stage "The administrator address"
say "The API grants the admin role to this address on every login, so no other"
say "account can take the dashboard — even if someone signs up first."
ask OBF_ADMIN_EMAIL "Administrator email:"
if [[ -z "${OBF_ADMIN_EMAIL:-}" ]]; then
  warn "An address is required; stopping here."
  exit 1
fi
write_env OBF_ADMIN_EMAIL "$OBF_ADMIN_EMAIL"

# ── 3. prove the database from this machine ───────────────────────────────
stage "Prove the database works — before deploying anything"
say "This opens the hosted database with the same code the API uses, creates"
say "the tables if they are missing, and prints what it finds."
pause "Press Enter to run the check"
_load_env
if ! "$(_py)" backend/tools/accounts_cli.py check; then
  warn "The check failed, so the URL or token above is wrong."
  warn "Fix it in Turso, then re-run this script: saved values are reused."
  exit 1
fi
say "Reachable, with the tables in place."

# ── 4. the public address, which every email link is built from ───────────
stage "The site's public address"
say "Verification and password-reset links are built from this, and so is the"
say "live check at the end. Use the address people actually open."
note "Without it the API falls back to http://localhost:8000, and every link"
note "in every email would point at the recipient's own machine."
ask OBF_APP_ORIGIN "Public origin (e.g. https://openbatteryflux.vercel.app):"
OBF_APP_ORIGIN="${OBF_APP_ORIGIN%/}"
case "${OBF_APP_ORIGIN:-}" in
  http://*|https://*) ;;
  *) warn "Include https:// — got: ${OBF_APP_ORIGIN:-nothing}"; exit 1 ;;
esac
case "$OBF_APP_ORIGIN" in
  *localhost*|*127.0.0.1*)
    warn "That is a local address: real readers would be sent to their own machine."
    confirm "Use it anyway?" || exit 1 ;;
esac
if [[ "$OBF_APP_ORIGIN" =~ -[a-z0-9]{8,}- ]]; then
  warn "That looks like a per-deployment URL (…-<hash>-…): it changes on every"
  warn "deploy and stays behind protection. The Production domain is better."
  confirm "Use it anyway?" || exit 1
fi
write_env OBF_APP_ORIGIN "$OBF_APP_ORIGIN"

# ── 5. a domain Resend is allowed to send from ────────────────────────────
stage "Resend: a domain you are allowed to send from"
say "Resend only sends from a domain whose DNS records you control. Without"
say "one, mail is limited to your own address and nobody else receives links."
open_url "https://resend.com/domains"
step "Add domain → type the domain you will send from."
step "Add the DNS records it shows (MX/SPF and DKIM) at your registrar."
step "Wait for the domain to read Verified — usually minutes, sometimes hours."
step "If you already have a verified domain, just confirm below."
pause "Press Enter once a domain shows Verified"

# ── 6. the key, the sender, and proof they agree ──────────────────────────
stage "Resend: API key and sender"
say "The key lets the deployed function send. Create it with sending access,"
say "not full access: it never needs to manage domains or read mail."
open_url "https://resend.com/api-keys"
step "Create API key → permission \"Sending access\" → create."
step "Copy it now: Resend shows it once."
ask_secret RESEND_API_KEY "Paste the API key:"
if [[ -z "${RESEND_API_KEY:-}" ]]; then
  warn "No key, no email; stopping here. Re-run when you have one."
  exit 1
fi
write_env RESEND_API_KEY "$RESEND_API_KEY"
step "Now the From line, on the domain you verified:"
step "   openBatteryFlux <no-reply@yourdomain.com>"
ask OBF_MAIL_FROM "From address:"
if [[ -z "${OBF_MAIL_FROM:-}" ]]; then
  warn "A sender is required, and it must be on the verified domain."
  exit 1
fi
write_env OBF_MAIL_FROM "$OBF_MAIL_FROM"
if _resend_check "$RESEND_API_KEY" "$OBF_MAIL_FROM"; then
  say "Resend accepts both."
else
  code=$?
  case "$code" in
    2) note "The check could not run offline; the live check at the end will" ;
       note "still catch a key the deployed function cannot use." ;;
    *) warn "Resend disagrees with the values above (the line before says how)."
       confirm "Continue anyway?" || exit 1 ;;
  esac
fi
pause "Press Enter to see what the server would send"

# ── the same values through the real configuration code ───────────────────
_load_env
say "What the API will do with these, read from the same code it runs:"
"$(_py)" - <<'PY'
from backend.app import mail

print("  delivery on        %s" % ("yes, through Resend" if mail.configured() else "no"))
print("  sender             %s" % mail.sender())
print("  links point at     %s" % mail.app_origin())
print("  a verify link      %s" % mail.verification_link("example-token"))
PY
note "With delivery on, a new account stays unverified until that link is"
note "opened, and the simulator tools stay locked until then."

# ── 7. the same values on Vercel ──────────────────────────────────────────
stage "Vercel: the six variables"
say "The deployed function reads these from its own environment. Vercel keeps"
say "them per environment: Production and Preview are separate lists."
SET_ALL=0
if _vercel_ready; then
  SET_ALL=1
  _vercel_env OBF_DATABASE_URL "$OBF_DATABASE_URL" production || SET_ALL=0
  _vercel_env OBF_DATABASE_TOKEN "$OBF_DATABASE_TOKEN" production || SET_ALL=0
  _vercel_env OBF_ADMIN_EMAIL "$OBF_ADMIN_EMAIL" production || SET_ALL=0
  _vercel_env RESEND_API_KEY "$RESEND_API_KEY" production || SET_ALL=0
  _vercel_env OBF_MAIL_FROM "$OBF_MAIL_FROM" production || SET_ALL=0
  _vercel_env OBF_APP_ORIGIN "$OBF_APP_ORIGIN" production || SET_ALL=0
fi
if (( SET_ALL == 1 )); then
  say "All six are set for Production."
else
  warn "Set them in the dashboard instead:"
  open_url "https://vercel.com/dashboard"
  step "Open your project → Settings → Environment Variables."
  step "OBF_DATABASE_URL    the turso:// URL saved in $ENV_FILE"
  step "OBF_DATABASE_TOKEN  the token saved in $ENV_FILE"
  step "OBF_ADMIN_EMAIL     $OBF_ADMIN_EMAIL"
  step "RESEND_API_KEY      the key saved in $ENV_FILE (sending access)"
  step "OBF_MAIL_FROM       $OBF_MAIL_FROM"
  step "OBF_APP_ORIGIN      $OBF_APP_ORIGIN"
  step "Tick Production (and Preview if you test there), then Save."
  pause "Press Enter once all six are saved"
fi
note "Preview deployments need their own copy if you want sign-in there too."

# ── 8. deployment protection ──────────────────────────────────────────────
stage "Deployment Protection"
say "If you can reach the sign-in form while other people cannot, it is because"
say "you are signed into Vercel in this browser: protection lets you through."
open_url "https://vercel.com/dashboard"
step "Open your project → Settings → Deployment Protection."
step "Vercel Authentication → choose \"Only Preview Deployments\", or turn it off."
step "Save. Leave Password Protection off."
note "Per-deployment URLs (…-<hash>-….vercel.app) stay private on purpose."
note "Share the Production domain or a custom domain instead."
pause "Press Enter when protection no longer covers Production"

# ── 9. redeploy ───────────────────────────────────────────────────────────
stage "Redeploy — new variables only reach a new deployment"
say "Saving a variable changes nothing for deployments that already exist."
DEPLOYED=0
if _vercel_ready; then
  if confirm "Deploy this working tree now with 'vercel --prod'?"; then
    if vercel --prod; then DEPLOYED=1; else warn "The CLI deploy failed; use the dashboard."; fi
  fi
fi
if (( DEPLOYED == 0 )); then
  open_url "https://vercel.com/dashboard"
  step "Open your project → Deployments → the newest row → ⋯ → Redeploy."
  pause "Press Enter once the new deployment is Ready"
fi

# ── 10. check the live site ───────────────────────────────────────────────
stage "Check the live site"
say "This is the check that would have caught \"unable to open database file\":"
say "the page, the API, the library, a sign-in attempt and a static file."
say "Testing $OBF_APP_ORIGIN"
while :; do
  if "$(_py)" backend/tools/smoke_test.py "$OBF_APP_ORIGIN"; then
    break
  fi
  warn "At least one check failed; the lines above name the one."
  note "DEPLOY.md section 9 maps each failure to its cause and fix."
  if ! confirm "Run the checks again?"; then
    warn "Stopping. Fix the failure above, then re-run this script."
    exit 1
  fi
done

# ── 11. the administrator, in the hosted database ─────────────────────────
stage "Create the administrator in the hosted database"
say "The hosted database starts empty: an account you made locally is not in it."
say "This creates (or promotes) $OBF_ADMIN_EMAIL, verified, with the password"
say "you type — so you can sign in before any email round trip."
pause "Press Enter to run ensure-admin"
_load_env
if ! "$(_py)" backend/tools/accounts_cli.py ensure-admin; then
  warn "ensure-admin failed; nothing was changed. Re-run to try again."
  exit 1
fi
"$(_py)" backend/tools/accounts_cli.py list || true
if confirm "Delete every other account in the hosted database (keeps $OBF_ADMIN_EMAIL)?"; then
  "$(_py)" backend/tools/accounts_cli.py purge --yes || warn "purge failed"
fi

finish
note "Sign in at $OBF_APP_ORIGIN/#/account with $OBF_ADMIN_EMAIL."
note "Anyone signing up now gets a verification link from $OBF_MAIL_FROM and"
note "must open it before the simulator tools unlock."
note "From now on, python3 backend/tools/smoke_test.py $OBF_APP_ORIGIN is the deploy check."
note "The tools read real environment variables, not $ENV_FILE, which is the record"
note "of what you set. Export the ones you need in a shell, or re-run this wizard"
note "— it offers everything it saved, so nothing has to be typed twice."
